import Foundation
import SwiftUI
import WidgetKit

// Shared runtime for Dynamic Widgets.
//
// This file is compiled into the VoltraWidget framework alongside the existing
// VoltraHomeWidget.swift, so widget extension code generated by the plugin can
// reference VoltraClientWidget* types without any per-widget glue duplicated.
//
// Pipeline:
//
//   1. Provider runs on a WidgetKit timeline tick.
//      - Fetches the JS bundle (dev = Metro HTTP, release = baked asset).
//      - Evaluates it once in the shared JSContext via VoltraJSRenderer.
//      - Emits a VoltraClientWidgetEntry with `bundleReady = true` (or errorMessage on failure).
//
//   2. ContentView body runs per (family, scheme, renderingMode) combo.
//      - Reads SwiftUI @Environment values (which are ONLY accessible inside a View body).
//      - Builds envJSON matching WidgetEnvironment in packages/core/src/widget-environment.ts.
//      - Calls VoltraJSRenderer.render(widgetId, propsJSON, envJSON) → resolved JSON string.
//      - Parses the resolved JSON into a VoltraNode and hands a VoltraHomeWidgetEntry to
//        the existing VoltraHomeWidgetView so Dynamic Widgets reach the same UI
//        renderer as server-rendered ones.
//
// When a stage fails (ADR 0013), a dev build shows an error view with the reason and a retry
// button; a release build keeps the last good render of this widget, instance and family, else the
// prerendered initial state.

// MARK: - Entry

public struct VoltraClientWidgetEntry: TimelineEntry {
  public let date: Date
  public let widgetId: String
  public let bundleReady: Bool
  /// Why the bundle could not be loaded or evaluated (ADR 0013). `nil` when it could.
  public let failure: DynamicWidgetRenderFailure?
  /// User-configured AppIntent parameters → `env.configuration`. Empty for widgets without an
  /// AppIntent configuration; populated by the generated AppIntentTimelineProvider from the
  /// configured intent.
  public let configuration: [String: String]
  /// The evaluated widget's JS bundle. Carried on the entry (not just left in the provider's
  /// JSContext) because WidgetKit archives entries and re-renders the View in a *fresh* extension
  /// process, where the provider's process-static JSContext is empty. The View re-evaluates from
  /// this source so `render()` always has the widget's function available in its own process.
  public let bundleSource: String?
  /// How the last server fetch went, as `env.serverUpdate`, for a widget that has a `serverUpdate`
  /// in app.json. `nil` for every other Dynamic Widget, and the reason `env.serverUpdate` is
  /// `undefined` there. Carried on the entry rather than read at render time because the provider
  /// is the thing that knows the fetch outcome, and WidgetKit re-renders archived entries in a
  /// fresh process.
  public let serverUpdateJSON: String?

  public init(
    date: Date,
    widgetId: String,
    bundleReady: Bool,
    failure: DynamicWidgetRenderFailure? = nil,
    configuration: [String: String] = [:],
    bundleSource: String? = nil,
    serverUpdateJSON: String? = nil
  ) {
    self.date = date
    self.widgetId = widgetId
    self.bundleReady = bundleReady
    self.failure = failure
    self.configuration = configuration
    self.bundleSource = bundleSource
    self.serverUpdateJSON = serverUpdateJSON
  }

  /// The same entry, drawn at another date: WidgetKit shows it from `date` on, and the render sees
  /// that date as `env.date`.
  public func at(_ date: Date) -> VoltraClientWidgetEntry {
    VoltraClientWidgetEntry(
      date: date,
      widgetId: widgetId,
      bundleReady: bundleReady,
      failure: failure,
      configuration: configuration,
      bundleSource: bundleSource,
      serverUpdateJSON: serverUpdateJSON
    )
  }

  /// The same entry, told how the server side is doing.
  public func withServerUpdate(_ serverUpdateJSON: String?) -> VoltraClientWidgetEntry {
    VoltraClientWidgetEntry(
      date: date,
      widgetId: widgetId,
      bundleReady: bundleReady,
      failure: failure,
      configuration: configuration,
      bundleSource: bundleSource,
      serverUpdateJSON: serverUpdateJSON
    )
  }
}

// MARK: - Provider

//
// Refresh model:
//
//   - DEBUG builds: Provider fetches `<id>.bundle` from Metro on every
//        `getTimeline`/`getSnapshot`, evaluates it in the shared JSContext, and emits
//        `bundleReady = true`. The ContentView then runs the freshly evaluated
//        `render(props, env)` and feeds the result to `VoltraHomeWidgetView`.
//
//   - Release builds: Provider loads the bundle baked into the extension by the "Bundle Voltra
//        Dynamic Content" build phase; on failure the ContentView renders the last good render,
//        else the prerendered initial state.
//
//   - Timeline policy is ALWAYS `.never`. The widget refreshes only when something
//        explicitly calls `WidgetCenter.shared.reloadAllTimelines()` or when WidgetKit
//        naturally re-invokes the Provider on its own lifecycle events (e.g., host app
//        foregrounding). iOS rate-limits timeline-policy-driven refresh aggressively
//        (~5-minute floor even in the simulator), so explicit reloads or natural
//        lifecycle re-invocations are the only mechanisms that deliver fresh content.

public struct VoltraClientWidgetProvider: TimelineProvider {
  public let widgetId: String
  /// Prerendered initial state JSON from `VoltraWidgetInitialStates.getInitialState(for:)`.
  /// Used as the placeholder, the Loading fallback, and the steady-state view if a bundle
  /// load fails.
  public let initialState: Data?

  public init(widgetId: String, initialState: Data? = nil) {
    self.widgetId = widgetId
    self.initialState = initialState
  }

  public func placeholder(in _: Context) -> VoltraClientWidgetEntry {
    VoltraClientWidgetEntry(date: Date(), widgetId: widgetId, bundleReady: false)
  }

  public func getSnapshot(in _: Context, completion: @escaping (VoltraClientWidgetEntry) -> Void) {
    Task { completion(await loadBundleEntry()) }
  }

  public func getTimeline(in _: Context, completion: @escaping (Timeline<VoltraClientWidgetEntry>) -> Void) {
    Task {
      let entry = await loadBundleEntry()
      completion(Timeline(entries: [entry], policy: .never))
    }
  }

  private func loadBundleEntry() async -> VoltraClientWidgetEntry {
    await VoltraClientWidgetProvider.loadEntry(widgetId: widgetId, configuration: [:])
  }

  /// Fetch + evaluate the widget bundle and build an entry. Shared by this `TimelineProvider` and
  /// the plugin-generated `AppIntentTimelineProvider`s (which pass the user-configured params as
  /// `configuration`).
  public static func loadEntry(widgetId: String, configuration: [String: String]) async -> VoltraClientWidgetEntry {
    let date = Date()

    let source: String
    do {
      source = try await VoltraClientWidgetBundleSource.load(widgetId: widgetId)
    } catch {
      return VoltraClientWidgetEntry(
        date: date,
        widgetId: widgetId,
        bundleReady: false,
        failure: DynamicWidgetRenderFailure(stage: .bundle, message: error.localizedDescription),
        configuration: configuration
      )
    }

    if case let .failure(failure) = VoltraJSRenderer.evaluateBundle(source: source, widgetId: widgetId) {
      return VoltraClientWidgetEntry(
        date: date,
        widgetId: widgetId,
        bundleReady: false,
        failure: failure,
        configuration: configuration
      )
    }
    return VoltraClientWidgetEntry(
      date: date,
      widgetId: widgetId,
      bundleReady: true,
      configuration: configuration,
      bundleSource: source
    )
  }
}

// MARK: - Bundle source (dev vs prod)

//
// Dual-path bundle loader. Dev reads from Metro localhost; prod reads from a baked asset
// in the extension's bundle, written there by the release-only "Bundle Voltra Dynamic Content"
// build phase.

public enum VoltraClientWidgetBundleSource {
  public enum LoadError: LocalizedError {
    case metroUnreachable(host: String, cause: String)
    case metroHTTP(code: Int, url: String, body: Data?)
    case nonUTF8
    case bakedBundleNotFound(path: String)

    public var errorDescription: String? {
      switch self {
      case let .metroUnreachable(host, cause):
        return DynamicWidgetBundleFailureMessage.metroUnreachable(host: host, cause: cause)
      case let .metroHTTP(code, url, body):
        return DynamicWidgetBundleFailureMessage.metroHTTP(code: code, url: url, body: body)
      case .nonUTF8:
        return "Bundle response was not UTF-8 text"
      case let .bakedBundleNotFound(path):
        return DynamicWidgetBundleFailureMessage.missingBakedAsset(path: path)
      }
    }
  }

  public static func load(widgetId: String) async throws -> String {
    #if DEBUG
      try await loadFromMetro(widgetId: widgetId)
    #else
      try loadFromBakedAsset(widgetId: widgetId)
    #endif
  }

  private static func loadFromMetro(widgetId: String) async throws -> String {
    // Dev mode = always-refetch. URLSession default cache policy is fine —
    // Metro's bundle responses are not cacheable, so each request hits the server.
    //
    // The base URL is relayed from the app via the app group (the app resolves it with
    // RCTBundleURLProvider; this extension is React-free). Falls back to localhost:8081 when the
    // app hasn't written it yet (e.g. first render before the host app has run).
    let base = VoltraWidgetDefaults.devServerURL() ?? "http://localhost:8081"
    let urlString = "\(base)/voltra/widgets/\(widgetId).bundle?platform=ios&dev=true"
    guard let url = URL(string: urlString) else {
      throw LoadError.metroUnreachable(host: base, cause: "invalid URL")
    }
    let data: Data
    let response: URLResponse
    do {
      (data, response) = try await URLSession.shared.data(from: url)
    } catch {
      throw LoadError.metroUnreachable(host: url.host.map { host in url.port.map { "\(host):\($0)" } ?? host } ?? base, cause: error.localizedDescription)
    }
    if let httpResponse = response as? HTTPURLResponse, !(200 ... 299).contains(httpResponse.statusCode) {
      throw LoadError.metroHTTP(code: httpResponse.statusCode, url: urlString, body: data)
    }
    guard let text = String(data: data, encoding: .utf8) else {
      throw LoadError.nonUTF8
    }
    return text
  }

  /// Release path: the "Bundle Voltra Dynamic Content" build phase writes
  /// `voltra-widget-<id>.bundle` into the extension's resources.
  private static func loadFromBakedAsset(widgetId: String) throws -> String {
    let name = "voltra-widget-\(widgetId).bundle"
    if let url = Bundle.main.url(forResource: "voltra-widget-\(widgetId)", withExtension: "bundle"),
       let text = try? String(contentsOf: url, encoding: .utf8)
    {
      return text
    }
    throw LoadError.bakedBundleNotFound(path: name)
  }
}

// MARK: - Env capture + JSON marshaling

//
// SwiftUI @Environment values are read inside the View body (see ContentView below) and
// passed here as plain values. This helper emits a JSON string matching the
// WidgetEnvironment type from packages/core/src/widget-environment.ts. We hand-roll the
// JSON instead of going through JSONSerialization so the shape is locked to that type and
// any drift produces a Swift compile error rather than a runtime parse failure.

public enum VoltraClientWidgetEnvBuilder {
  public static func build(
    date: Date,
    widgetFamily: WidgetFamily,
    colorScheme: ColorScheme?,
    widgetRenderingMode: WidgetRenderingMode,
    showsWidgetContainerBackground: Bool,
    locale: Locale,
    layoutDirection: LayoutDirection? = nil,
    configuration: [String: String],
    serverUpdateJSON: String? = nil
  ) -> String {
    let timestampMs = Int(date.timeIntervalSince1970 * 1000)
    let appVersion = Bundle.main.infoDictionary?["CFBundleShortVersionString"] as? String ?? "unknown"
    let voltraVersion = VoltraConfig.voltraVersion()

    #if DEBUG
      let isDev = true
      let metroUrl: String? = VoltraWidgetDefaults.devServerURL() ?? "http://localhost:8081"
    #else
      let isDev = false
      let metroUrl: String? = nil
    #endif

    let metroUrlLiteral = metroUrl.map(jsonString) ?? "null"
    let buildJSON = """
    {
      "isDev": \(isDev),
      "metroUrl": \(metroUrlLiteral),
      "appVersion": \(jsonString(appVersion)),
      "voltraVersion": \(jsonString(voltraVersion))
    }
    """

    let configurationJSON: String
    if configuration.isEmpty {
      configurationJSON = "{}"
    } else {
      let entries = configuration
        .map { "\(jsonString($0.key)): \(jsonString($0.value))" }
        .joined(separator: ", ")
      configurationJSON = "{ \(entries) }"
    }

    // Only a server-driven widget gets env.serverUpdate; leaving the key out entirely is what
    // makes it `undefined` for every other Dynamic Widget.
    let serverUpdateEntry = serverUpdateJSON.map { ",\n  \"serverUpdate\": \($0)" } ?? ""

    // The instance key (ADR 0007): the hash of this placement's merged configuration, or absent
    // for a widget with no configuration parameters at all — matching what the request builder
    // sends and what WidgetScope.of(widgetId, configuration:) resolves to.
    let instanceEntry = WidgetCanonicalConfiguration.key(configuration).map { ",\n  \"instance\": \(jsonString($0))" } ?? ""

    // Locale fields (ADR 0009 §1). `locale` is BCP-47 (`pl-PL`), never the ICU `pl_PL` that
    // `Locale.identifier` gives and `Intl` rejects.
    let localeEnvironment = VoltraLocaleEnvironment.capture(
      locale: locale,
      isRightToLeft: layoutDirection.map { $0 == .rightToLeft },
      appLocale: VoltraWidgetDefaults.dynamicWidgetLocale()
    )

    return """
    {
      "date": \(timestampMs),
      "widgetFamily": \(jsonString(familyString(widgetFamily))),
      "colorScheme": \(jsonString(schemeString(colorScheme))),
      \(localeEnvironment.jsonFields),
      "widgetRenderingMode": \(jsonString(renderingModeString(widgetRenderingMode))),
      "showsWidgetContainerBackground": \(showsWidgetContainerBackground),
      "configuration": \(configurationJSON),
      "build": \(buildJSON)\(serverUpdateEntry)\(instanceEntry)
    }
    """
  }

  /// All three SwiftUI enums have String(describing:) representations that match their
  /// case names exactly (e.g. "systemMedium", "fullColor", "dark"). Using String(describing:)
  /// keeps these helpers forward-compatible when Apple adds new cases in a future SDK.
  private static func familyString(_ family: WidgetFamily) -> String {
    String(describing: family)
  }

  private static func renderingModeString(_ mode: WidgetRenderingMode) -> String {
    String(describing: mode)
  }

  private static func schemeString(_ scheme: ColorScheme?) -> String {
    guard let scheme else { return "light" }
    return String(describing: scheme)
  }

  private static func jsonString(_ value: String) -> String {
    let escaped = value
      .replacingOccurrences(of: "\\", with: "\\\\")
      .replacingOccurrences(of: "\"", with: "\\\"")
      .replacingOccurrences(of: "\n", with: "\\n")
      .replacingOccurrences(of: "\r", with: "\\r")
    return "\"\(escaped)\""
  }
}

// MARK: - Content view

//
// Per Q5 grilling: the resolved JSON is parsed into a VoltraNode and rendered via the
// existing VoltraHomeWidgetView so Dynamic Widgets are visually indistinguishable
// from server-rendered ones at the UI layer.

public struct VoltraClientWidgetContentView: View {
  public let entry: VoltraClientWidgetEntry
  public let initialState: Data?
  /// The dev error view's retry button, supplied by the extension (see `VoltraDynamicWidgetErrorView`).
  public let retryButton: VoltraDynamicWidgetRetryButton?

  @Environment(\.widgetFamily) private var widgetFamily
  @Environment(\.colorScheme) private var colorScheme
  @Environment(\.widgetRenderingMode) private var widgetRenderingMode
  @Environment(\.showsWidgetContainerBackground) private var showsWidgetContainerBackground
  @Environment(\.locale) private var locale
  @Environment(\.layoutDirection) private var layoutDirection

  public init(entry: VoltraClientWidgetEntry, initialState: Data?, retryButton: VoltraDynamicWidgetRetryButton? = nil) {
    self.entry = entry
    self.initialState = initialState
    self.retryButton = retryButton
  }

  public var body: some View {
    switch shownContent() {
    case let .devError(failure):
      VoltraDynamicWidgetErrorView(widgetId: entry.widgetId, failure: failure, family: widgetFamily, retryButton: retryButton)
    case let .node(node), let .lastGood(node), let .placeholder(node):
      VoltraHomeWidgetView(entry: VoltraHomeWidgetEntry(date: entry.date, rootNode: node, widgetId: entry.widgetId))
    case .loading:
      VoltraHomeWidgetView(entry: VoltraHomeWidgetEntry(date: entry.date, rootNode: nil, widgetId: entry.widgetId))
    }
  }

  private var isDev: Bool {
    #if DEBUG
      true
    #else
      false
    #endif
  }

  private var renderKey: DynamicWidgetRenderKey {
    DynamicWidgetRenderKey(
      widgetId: entry.widgetId,
      instance: WidgetCanonicalConfiguration.key(entry.configuration),
      family: String(describing: widgetFamily),
      appearance: "\(String(describing: colorScheme))-\(String(describing: widgetRenderingMode))-\(showsWidgetContainerBackground)"
    )
  }

  /// Renders this placement and decides what to draw (ADR 0013 §3). An entry that is not ready and
  /// carries no failure is WidgetKit's placeholder, which has always drawn the prerendered state.
  private func shownContent() -> DynamicWidgetShownContent<VoltraNode> {
    let key = renderKey
    let outcome: Result<VoltraNode, DynamicWidgetRenderFailure>
    if let failure = entry.failure {
      outcome = .failure(failure)
    } else if entry.bundleReady {
      outcome = renderNode()
    } else {
      return initialState.flatMap(parseResolvedNode(jsonData:)).map { .placeholder($0) } ?? .loading
    }

    switch outcome {
    case let .failure(failure):
      DynamicWidgetFailureLog.shared.failed(key: key, failure: failure, isDev: isDev)
    case .success:
      DynamicWidgetFailureLog.shared.succeeded(key: key)
    }

    return DynamicWidgetShownContent.resolve(
      isDev: isDev,
      result: outcome,
      lastGood: {
        DynamicWidgetLastGoodStore.shared?.read(key).flatMap { parseResolvedNode(jsonString: $0) }
      },
      placeholder: { initialState.flatMap(parseResolvedNode(jsonData:)) }
    )
  }

  private func renderNode() -> Result<VoltraNode, DynamicWidgetRenderFailure> {
    // WidgetKit may render this archived entry in a fresh extension process where the provider's
    // bundle evaluation didn't happen. Re-evaluate from the entry's carried source (no-op if this
    // process already has it) so render() finds the widget's function.
    if let source = entry.bundleSource,
       case let .failure(failure) = VoltraJSRenderer.ensureEvaluated(widgetId: entry.widgetId, source: source)
    {
      return .failure(failure)
    }
    let envJSON = VoltraClientWidgetEnvBuilder.build(
      date: entry.date,
      widgetFamily: widgetFamily,
      colorScheme: colorScheme,
      widgetRenderingMode: widgetRenderingMode,
      showsWidgetContainerBackground: showsWidgetContainerBackground,
      locale: locale,
      layoutDirection: layoutDirection,
      configuration: entry.configuration,
      serverUpdateJSON: entry.serverUpdateJSON
    )
    // This placement's scope (ADR 0007): an instance of its merged configuration, or the plain
    // widget scope when it has none — which is also every widget's scope before this ADR.
    let scope = WidgetScope.of(entry.widgetId, configuration: entry.configuration)
    let dynamicWidgetPropsStore = DynamicWidgetPropsStore()
    let dynamicWidgetRenderCoordinator = DynamicWidgetRenderCoordinator(
      // Reads the instance slot for `scope`'s key, falling back to the widget slot when the
      // placement has not fetched yet or has no configuration.
      dynamicWidgetPropsProvider: { _ in dynamicWidgetPropsStore.dynamicWidgetProps(for: scope) },
      dynamicWidgetRuntimeBoundary: { dynamicWidgetID, dynamicWidgetPropsJSON, dynamicWidgetEnvironmentJSON in
        VoltraJSRenderer.render(
          widgetId: dynamicWidgetID,
          propsJSON: dynamicWidgetPropsJSON,
          envJSON: dynamicWidgetEnvironmentJSON
        )
      }
    )
    let resolved: String
    switch dynamicWidgetRenderCoordinator.renderDynamicWidget(
      dynamicWidgetID: entry.widgetId,
      dynamicWidgetEnvironmentJSON: envJSON
    ) {
    case let .failure(failure):
      return .failure(failure)
    case let .success(json):
      resolved = json
    }
    guard let node = parseResolvedNode(jsonString: resolved) else {
      return .failure(DynamicWidgetRenderFailure(stage: .parse, message: "render() returned JSON that did not parse into a node"))
    }
    // Written in every build so dev runs exercise the path; only release reads it back.
    DynamicWidgetLastGoodStore.shared?.write(resolved, for: renderKey)
    return .success(node)
  }

  private func parseResolvedNode(jsonString: String) -> VoltraNode? {
    guard let json = try? JSONValue.parse(from: jsonString) else { return nil }
    let node = VoltraNode.parse(from: json)
    if case .empty = node {
      return nil
    }
    return node
  }

  private func parseResolvedNode(jsonData: Data) -> VoltraNode? {
    guard let text = String(data: jsonData, encoding: .utf8) else { return nil }
    return parseResolvedNode(jsonString: text)
  }
}
